<script setup>
import BrowserSessionList from './BrowserSessionList.vue'
import BrowserSessionPanel from './BrowserSessionPanel.vue'
</script>

<template>
  <div class="w-full h-full flex flex-col">
    <!-- Mobile: Toggle Header -->
    <div v-if="isMobile" class="flex items-center gap-2 p-3 border-b border-base-content/10 bg-base-200">
      <button
        v-if="selectedSessionId"
        @click="clearSelection"
        class="btn btn-sm btn-ghost btn-circle"
        title="Back to list"
      >
        <i class="fa-solid fa-arrow-left"></i>
      </button>
      <h1 class="text-lg font-bold flex-1">Browser Sessions</h1>
    </div>

    <!-- Main Content -->
    <div v-if="!isMobile" class="flex flex-1 gap-3 p-3 overflow-hidden bg-base-100">
      <!-- Desktop: collapsible sidebar (side-by-side layout) -->
      <aside
        class="flex-shrink-0 border border-base-content/10 rounded-lg overflow-hidden flex flex-col bg-base-100 transition-[width] duration-200 ease-out"
        :class="sidebarCollapsed ? 'w-16' : 'w-80'"
      >
        <BrowserSessionList
          :collapsed="sidebarCollapsed"
          @toggle-collapse="toggleSidebar"
        />
      </aside>
      <div class="flex-1 min-w-0 border border-base-content/10 rounded-lg overflow-hidden flex flex-col bg-base-100">
        <BrowserSessionPanel />
      </div>
    </div>

    <!-- Mobile: Single column -->
    <div v-else class="flex-1 overflow-hidden flex flex-col">
      <Transition
        name="fade-slide"
        mode="out-in"
      >
        <div v-if="showList" key="list" class="flex-1 overflow-hidden">
          <BrowserSessionList :collapsed="false" />
        </div>
        <div v-else-if="showPanel" key="panel" class="flex-1 overflow-hidden">
          <BrowserSessionPanel />
        </div>
      </Transition>
    </div>
  </div>
</template>
<script>
const SIDEBAR_STATE_KEY = 'codx.browsers.sidebarCollapsed'

export default {
  name: 'BrowsersSessionManager',
  components: {
    BrowserSessionList,
    BrowserSessionPanel
  },
  data() {
    return {
      sidebarCollapsed: false
    }
  },
  computed: {
    isMobile() {
      return this.$storex.ui.isMobile
    },
    selectedSessionId() {
      return this.$storex.browsers.selectedSessionId
    },
    showList() {
      if (this.isMobile) {
        return !this.selectedSessionId
      }
      return true
    },
    showPanel() {
      if (this.isMobile) {
        return !!this.selectedSessionId
      }
      return true
    }
  },
  watch: {
    sidebarCollapsed(value) {
      this.saveSidebarState(value)
    }
  },
  methods: {
    toggleSidebar() {
      this.sidebarCollapsed = !this.sidebarCollapsed
    },
    clearSelection() {
      this.$storex.browsers.clearSelection()
    },
    loadSidebarState() {
      try {
        return window.localStorage.getItem(SIDEBAR_STATE_KEY) === 'true'
      } catch (error) {
        return false
      }
    },
    saveSidebarState(value) {
      try {
        window.localStorage.setItem(SIDEBAR_STATE_KEY, value ? 'true' : 'false')
      } catch (error) {
        // localStorage not available
      }
    }
  },
  mounted() {
    this.sidebarCollapsed = this.loadSidebarState()
  },
  inject: ['$storex']
}
</script>
